def scan_filesystem(self, scan_dirs: List[str] = None) -> List[SoftwareInfo]:
        """Scan filesystem for proprietary binaries."""
        if scan_dirs is None:
            scan_dirs = self.config.get('scan_directories', ['/usr/bin', '/usr/local/bin', '/opt', '/home'])

        # Add Flatpak installation directories if they exist
        flatpak_dirs = [
            '/var/lib/flatpak/app',
            '/var/lib/flatpak/runtime',
            os.path.expanduser('~/.local/share/flatpak/app'),
            os.path.expanduser('~/.local/share/flatpak/runtime')
        ]

        for flatpak_dir in flatpak_dirs:
            if os.path.exists(flatpak_dir) and flatpak_dir not in scan_dirs:
                scan_dirs.append(flatpak_dir)

        results = []

        for directory in scan_dirs:
            if not os.path.exists(directory):
                continue

            try:
                for root, dirs, files in os.walk(directory):
                    # Skip hidden directories and excluded directories
                    dirs[:] = [d for d in dirs if not d.startswith('.') and d not in self.exclude_directories]

                    for file in files:
                        file_path = os.path.join(root, file)
                        if self._is_executable(file_path):
                            license_type = self._analyze_binary(file_path)
                            if license_type == 'proprietary':
                                results.append(SoftwareInfo(
                                    name=file,
                                    version='',
                                    license_type=license_type,
                                    source='file_system',
                                    path=file_path
                                ))
            except PermissionError:
                continue

        return results
